import { test, expect } from '@playwright/test';

test.describe('Mark record as favourite', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/records');
  });

  test('should mark a record as favourite', async ({ page }) => {
    await page.getByText('Record Title 1').click();
    await page.getByRole('button', { name: 'Mark as Favourite' }).click();
    const favouriteMessage = await page.getByText('Record marked as favourite');
    await expect(favouriteMessage).toBeVisible();
  });

  test('should show favourite status on record list', async ({ page }) => {
    await page.getByText('Record Title 1').click();
    await page.getByRole('button', { name: 'Mark as Favourite' }).click();
    await page.goto('/records');
    const favouriteIndicator = await page.getByText('★ Record Title 1');
    await expect(favouriteIndicator).toBeVisible();
  });
});
